<script setup lang="ts">
import CreatorHeader from '@/components/CreatorHeader.vue'
import '@/styles/creator-theme.css'
import { computed, nextTick, ref, onMounted, onUnmounted, watch } from 'vue'
import { examples, makeWork, normalizeWork, gameHtml, buildPreview, encodeWork, decodeWork, type GameWork, type GameKind } from '@/demo/games'
import { useReplay } from '@/demo/useReplay'
import { zipSync } from 'fflate'
import { sourceFiles, type SourceFormat } from '@/demo/sourceExport'
import { publicAssetFiles, modelAssets, dataUri } from '@/demo/publicAssets'
import { artAssets } from '@/demo/artAssets'
import { replayStages } from '@/demo/replayScripts'
import { engines, enginePlan, type EngineId } from '@/demo/engines'
import { gameElements, editGameElement, type GameElement } from '@/demo/elementEditing'
const selectedEngine=ref<EngineId>('web')
const engineDetails=computed(()=>engines.find(e=>e.id===selectedEngine.value)!)
function downloadEnginePlan(){downloadBlob(new Blob([enginePlan(selectedEngine.value,work.value.name)],{type:'application/json'}),'engine-plan.json')}
const previewFrame=ref<HTMLIFrameElement>();const editMode=ref(false);const selectedElement=ref<GameElement>();
function syncEditMode(){previewFrame.value?.contentWindow?.postMessage({type:'idea2game:edit-mode',enabled:editMode.value&&comparisonSide.value==='after',selectedId:selectedElement.value?.id},'*')}
function toggleElements(){editMode.value=!editMode.value;replayMode.value=false;input.value='';syncEditMode()}
function receiveElement(event:MessageEvent){if(event.source!==previewFrame.value?.contentWindow||event.data?.type!=='idea2game:element-selected')return;const target=gameElements.find(e=>e.id===event.data.element?.id);if(target){selectedElement.value=target;replayMode.value=false;input.value='';}}
onMounted(()=>window.addEventListener('message',receiveElement));onUnmounted(()=>window.removeEventListener('message',receiveElement));
const work = ref<GameWork>(makeWork('history'))
const requestedExample = new URLSearchParams(location.search).get('example')
if (examples.some(e => e.kind === requestedExample)) work.value = makeWork(requestedExample as GameKind)
const input = ref('')
const notice = ref('')
const mobile = ref(false)
const hostedPreview=ref(false)
const hostedUrl=computed(()=>new URL('play/'+work.value.kind+'/index.html',location.origin+import.meta.env.BASE_URL).href+'#work='+encodeURIComponent(encodeWork(work.value)))
async function downloadDeployment(){try{const runtime=await(await getFile(runtimeUrl)).text(),art=work.value.art?new Uint8Array(await(await getFile(artUrl)).arrayBuffer()):new Uint8Array();const files=sourceFiles(work.value,runtime,art,'web-js',await gameResources());files['DEPLOY.md']=new TextEncoder().encode('解压后将完整目录上传Cloudflare Pages Direct Upload。index.html、src/game/runtime.js、assets必须同时上传。当前ZIP无需Unity/Godot或后端。部署URL以Cloudflare实际返回为准。参考站素材权利与来源见assets/reference/SOURCES.txt。');downloadBlob(new Blob([new Uint8Array(zipSync(files,{level:6}))],{type:'application/zip'}),'idea2game-cloudflare-web.zip');notice.value='已下载Cloudflare可部署Web包；尚未发布到你的Cloudflare账号。'}catch{notice.value='部署包生成失败，请重试。'}}
const playOnly = ref(new URLSearchParams(location.search).get('play') === '1')
const saved = ref<GameWork[]>([])
const chatBox = ref<HTMLElement>()
const busy = ref(false)
const replayMode=ref(false)
const runtimeUrl = new URL('demo-games/runtime.js',location.origin + import.meta.env.BASE_URL).href
const replay=useReplay(()=>nextTick(()=>chatBox.value?.scrollTo({top:chatBox.value.scrollHeight})))
const {stage,running,paused,messages}=replay
const inspectorTab=ref<'objects'|'assets'>('objects')
const recordOpen=ref(false)
const comparisonSide=ref<'before'|'after'>('after')
const lastChange=ref<{before:GameWork;after:GameWork}>()
let skipComparison=false
watch(work,(after,before)=>{comparisonSide.value='after';if(skipComparison){skipComparison=false;lastChange.value=undefined;return}if(after.id!==before.id||after.kind!==before.kind){lastChange.value=undefined;return}if(JSON.stringify({...after,updatedAt:''})!==JSON.stringify({...before,updatedAt:''}))lastChange.value={before:JSON.parse(JSON.stringify(before)),after:JSON.parse(JSON.stringify(after))};})
const availableElements=computed(()=>gameElements.filter(e=>work.value.kind==='tiles'?['cards','scene'].includes(e.id):e.id!=='cards'&&(e.id!=='weapon'||work.value.kind==='history')))
function selectObject(element:GameElement){selectedElement.value=element;editMode.value=true;comparisonSide.value='after';syncEditMode();}
const elementNames:Record<string,string>={player:'玩家角色',weapon:'环绕飞刀',enemy:'敌人',scene:'场景',cards:'卡牌图案'}
const propertyNames:Record<string,string>={color:'颜色',scale:'大小',hp:'生命值',count:'飞刀数量',speed:'旋转速度'}
const objectProperties=computed(()=>{const id=selectedElement.value?.id;if(!id)return[];const value=work.value.elementEdits?.[id]||{};const keys=id==='scene'?['color']:id==='cards'?['scale']:id==='weapon'?['color','scale','count','speed']:id==='player'?['color','scale','hp']:['color','scale'];return keys.map(key=>({key,name:propertyNames[key],value:value[key as keyof typeof value]??(key==='color'?(id==='player'&&work.value.kind==='history'?'#a9402d':work.value.color):key==='hp'?(work.value.kind==='zombies'?150:100):1)}))})
function updateProperty(key:string,event:Event){const id=selectedElement.value?.id;if(!id)return;const raw=(event.target as HTMLInputElement).value;const ranges:Record<string,[number,number]>={scale:[.5,2],hp:[1,500],count:[1,9],speed:[.5,3]};const range=ranges[key];const value=key==='color'?raw:Math.min(range![1],Math.max(range![0],Number(raw)||range![0]));work.value={...work.value,elementEdits:{...work.value.elementEdits,[id]:{...work.value.elementEdits?.[id],[key]:value}},updatedAt:new Date().toISOString()};notice.value='属性已应用，右侧显示新版本。'}
const comparisonRows=computed(()=>{if(!lastChange.value)return[];const {before,after}=lastChange.value;const rows:{name:string;before:string;after:string}[]=[];for(const key of ['difficulty','speed','color','name','view','art'] as const)if(before[key]!==after[key])rows.push({name:({difficulty:'难度',speed:'游戏速度',color:'主题颜色',name:'游戏名称',view:'视角',art:'封面素材'})[key],before:String(before[key]),after:String(after[key])});for(const id of Object.keys(after.elementEdits||{})){const a=after.elementEdits?.[id]||{},b=before.elementEdits?.[id]||{};for(const key of Object.keys(a) as (keyof typeof a)[])if(a[key]!==b[key])rows.push({name:elementNames[id]+' · '+propertyNames[key],before:String(b[key]??(key==='hp'?(before.kind==='zombies'?150:100):key==='color'?(id==='player'&&before.kind==='history'?'#a9402d':before.color):1)),after:String(a[key])});}return rows;})
function undoChange(){if(!lastChange.value)return;const previous=lastChange.value.before;skipComparison=true;work.value={...previous,updatedAt:new Date().toISOString()};lastChange.value=undefined;notice.value='已撤销最近一次修改。'}

const assetOverrides=ref<Record<string,string>>({})
let resourceCache:Promise<Record<string,Uint8Array>>|undefined
const resources=()=>resourceCache??=Promise.all(publicAssetFiles.map(async name=>[name,new Uint8Array(await(await getFile(runtimeUrl.replace(/runtime\.js$/,name))).arrayBuffer())] as const)).then(entries=>Object.fromEntries(entries)).catch(error=>{resourceCache=undefined;throw error})
watch(()=>work.value.kind,async kind=>{if(kind!=='zombies'||Object.keys(assetOverrides.value).length)return;try{const files=await resources();assetOverrides.value=Object.fromEntries(Object.entries(files).filter(([name])=>/\.(glb|webp|png)$/.test(name)).map(([name,bytes])=>[name,dataUri(bytes,name.endsWith('.glb')?'model/gltf-binary':name.endsWith('.webp')?'image/webp':'image/png')]));}catch{notice.value='公开模型载入失败，点击重新载入可重试。'}},{immediate:true})
const previewWork=computed(()=>comparisonSide.value==='before'&&lastChange.value?lastChange.value.before:work.value)
const frameHtml = computed(() => buildPreview(previewWork.value,runtimeUrl,work.value.kind==='zombies'&&Object.keys(assetOverrides.value).length===0?0:stage.value,assetOverrides.value))
function generate(){hostedPreview.value=false;editMode.value=false;selectedElement.value=undefined;comparisonSide.value='after';replay.begin(work.value.kind,input.value.trim()||examples.find(e=>e.kind===work.value.kind)?.prompt||'制作双路线数字增援射击游戏');input.value=''}
function restartReplay(){input.value=examples.find(e=>e.kind===work.value.kind)?.prompt||'';generate()}
function showFinished(){replayMode.value=false;input.value='';selectedElement.value=undefined;editMode.value=false;stage.value=5;messages.value=[{role:'assistant',type:'result',title:'游戏已就绪',text:'点击右侧开始游戏。你可以调整难度与速度，选中游戏元素修改颜色、大小或属性，再保存作品、下载源码或分享试玩链接。'}]}
function showInitial(){if(playOnly.value||new URLSearchParams(location.hash.slice(1)).has('work')){showFinished();return}replayMode.value=true;stage.value=0;input.value=examples.find(e=>e.kind===work.value.kind)?.prompt||'';selectedElement.value=undefined;editMode.value=false;messages.value=[{role:'assistant',text:'已为你准备游戏需求。可以直接发送，也可以先修改玩法描述；右侧将随制作过程逐步搭建。'}]}
onMounted(showInitial)
watch(selectedElement,()=>nextTick(syncEditMode))
const hashWork = new URLSearchParams(location.hash.slice(1)).get('work')
if(hashWork) { try {work.value=decodeWork(hashWork)}catch {notice.value='分享数据无效，已打开默认样例。'} }
try { const stored = JSON.parse(localStorage.getItem('forge-demo-works') || '[]'); if(Array.isArray(stored)) saved.value=stored.slice(0,12).map(normalizeWork) } catch {notice.value='无法读取本机作品；仍可试玩、下载和分享。'}
function choose(kind: GameKind) { replay.cancel();work.value=makeWork(kind);notice.value='';shareUrl.value='';input.value=examples.find(e=>e.kind===kind)?.prompt||'';showInitial() }
function send() {
 const text=input.value.trim();if(running.value)return;if(replayMode.value){generate();return;}if(stage.value<5){generate();return}if(!text||busy.value)return;messages.value.push({role:'user',text});input.value='';busy.value=true
 if(selectedElement.value){const result=editGameElement(work.value,selectedElement.value,text);if(result.changes.length){work.value={...result.work,updatedAt:new Date().toISOString()};messages.value.push({role:'assistant',text:'已修改'+selectedElement.value.name+'：'+result.changes.join('、')+'。修改已写入作品，保存、分享和源码导出均会保留。'});}else messages.value.push({role:'assistant',text:'当前选中'+selectedElement.value.name+'。当前支持颜色、大小；玩家支持生命值，转刀武器支持数量和转速。自由修改需正式AI后端。'});busy.value=false;return;}
 const changed:string[]=[];let next={...work.value}
 const kind:GameKind|undefined = /叠层|三消|羊了个羊|消除/.test(text)?'tiles':/数字门|倍率|双轨|跑酷/.test(text)?'zombies':/僵尸|守城/.test(text)?'zombies':/武侠|历史|武将|大乱斗|肉鸽/.test(text)?'history':undefined
 if(kind && kind!==next.kind){next=makeWork(kind);changed.push('切换可玩模板')}
 const difficulty=text.match(/难度(?:设为|设置为|改为|调到|为)?\s*([123])/)
 if(difficulty){next.difficulty=Number(difficulty[1]);changed.push(`难度 ${next.difficulty}`)}
 if(/慢|简单|容易/.test(text)){next.speed=Math.max(.5,next.speed*.75);changed.push('速度降低25%')}
 if(/快|困难|难一点/.test(text)){next.speed=Math.min(2,next.speed*1.25);changed.push('速度提高25%')}
 const colors:{[key:string]:string}={'紫':'#a78bfa','蓝':'#71b7ff','绿':'#7de4bf','粉':'#ff91bd','橙':'#ffae70'}
 for(const [key,value] of Object.entries(colors))if(text.includes(key+'色')){next.color=value;changed.push('主题颜色已修改');break}
 for(const hero of ['弓将','铁卫','谋士'])if(text.includes(hero)){next.hero=hero;next.kind='history';changed.push(`武将改为${hero}`);break}
 const title=text.match(/(?:名字|名称|游戏名)(?:改成|改为|叫|设为|：|:)\s*[「“"]?([^「」“”"\n，。]{1,36})/)
 if(title){next.name=title[1]!.trim();changed.push('作品已改名')}
 if(/2\.5[Dd]|2.5维|斜视|等距/.test(text)&&next.kind==='history'){next.view='2.5d';changed.push('切换2.5D斜视战场')}else if(/2[Dd]|二维|俯视/.test(text)&&next.kind==='history'){next.view='2d';changed.push('保留原玩法，切换2D俯视版本')}
 if(/重开|重新开始/.test(text))changed.push('重新开始')
 if(changed.length){work.value={...next,updatedAt:new Date().toISOString()};messages.value.push({role:'assistant',text:`已应用：${changed.join('、')}。点击开始重新试玩。`})}
 else messages.value.push({role:'assistant',text:'当前支持调整速度、难度、颜色、名称和武将；自由生成新玩法需要连接AI后端。试试「速度慢一点，改成紫色」或选择上方案例。'})
 busy.value=false;nextTick(()=>chatBox.value?.scrollTo({top:chatBox.value.scrollHeight,behavior:'smooth'}))
}
function save() {try{const item=normalizeWork({...work.value,updatedAt:new Date().toISOString()});const list=[item,...saved.value.filter(w=>w.id!==item.id)].slice(0,12);localStorage.setItem('forge-demo-works',JSON.stringify(list));saved.value=list;notice.value='作品已保存在当前浏览器，刷新后仍可继续。'}catch{notice.value='浏览器不允许本机保存，请下载游戏或复制分享链接。'} }
const shareUrl=ref('')
async function share(){const url=new URL(location.href);url.search='?play=1';url.hash='work='+encodeURIComponent(encodeWork(work.value));shareUrl.value=url.href;try{await navigator.clipboard.writeText(url.href);notice.value='试玩链接已复制，发给朋友即可玩。'}catch{notice.value='复制下方链接发给朋友。'} }
const artUrl=runtimeUrl.replace(/runtime\.js$/, 'art-showcase.png')
const selectedAsset=ref<(typeof artAssets)[number]>()
async function getFile(url:string){const r=await fetch(url);if(!r.ok)throw Error('文件读取失败');return r}
async function gameResources():Promise<Record<string,Uint8Array>>{return work.value.kind==='zombies'?resources():work.value.kind==='tiles'?{'farm-atlas.png':new Uint8Array(await(await getFile(runtimeUrl.replace(/runtime\.js$/,'farm-atlas.png'))).arrayBuffer())}:{}}
function downloadBlob(blob:Blob,name:string){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function download(){try{
 const runtime=await(await getFile(runtimeUrl)).text(),files=await gameResources();
 const overrides=Object.fromEntries(Object.entries(files).filter(([name])=>/\.(glb|png|webp)$/.test(name)).map(([name,bytes])=>[name,dataUri(bytes,name.endsWith('.glb')?'model/gltf-binary':name.endsWith('.webp')?'image/webp':'image/png')]));
 let html=gameHtml(work.value,runtimeUrl,5,overrides);
 const inline=(code:string)=>'<script>'+code.replace(/<\/script/gi,'<\\/script')+'</scr'+'ipt>';
 html=html.replace('<script src="'+runtimeUrl+'"></scr'+'ipt>',()=>inline(runtime));
 if(files['expedition-renderer.js'])html=html.replace(/<script src="[^"]*expedition-renderer.js"><\/script>/,()=>inline(new TextDecoder().decode(files['expedition-renderer.js'])));
 for(const [name,bytes] of Object.entries(files))if(/\.(png|webp)$/.test(name))html=html.split(runtimeUrl.replace(/runtime\.js$/,name)).join(dataUri(bytes,name.endsWith('.webp')?'image/webp':'image/png'));
 if(work.value.art){const bytes=new Uint8Array(await(await getFile(artUrl)).arrayBuffer());html=html.split(artUrl).join(dataUri(bytes,'image/png'));}
 const licenses=Object.entries(files).filter(([name])=>name.endsWith('LICENSE.txt')).map(([name,bytes])=>name+'\n'+new TextDecoder().decode(bytes)).join('\n\n');
 if(licenses)html=html.replace('</body>',()=>'<script type="text/plain" id="asset-licenses">'+licenses.replace(/<\/script/gi,'<\\/script')+'</scr'+'ipt></body>');
 downloadBlob(new Blob([html],{type:'text/html'}),'my-game.html');notice.value='已下载独立HTML，运行时、使用的模型和图片均已内嵌。';
 }catch{notice.value='下载失败，请重试。'}}
const sourceFormat=ref<SourceFormat>('web-js')
async function downloadSource(){if(sourceFormat.value==='single-html'){await download();return}try{const runtime=await(await getFile(runtimeUrl)).text();const art=work.value.art?new Uint8Array(await(await getFile(artUrl)).arrayBuffer()):new Uint8Array();const files=sourceFiles(work.value,runtime,art,sourceFormat.value,await gameResources());const bytes=zipSync(files,{level:6});downloadBlob(new Blob([new Uint8Array(bytes)],{type:'application/zip'}),`idea2game-${sourceFormat.value}.zip`);notice.value=sourceFormat.value==='vite-ts'?'已下载TypeScript入口 + JavaScript运行时的Vite工程，解压后按README运行。':'已下载完整Web工程：src游戏代码、assets图片、参数与README。'}catch{notice.value='源码包下载失败，请重试。'}}
function applyArt(){work.value={...work.value,art:true,updatedAt:new Date().toISOString()};notice.value='已应用AI封面；重新开始时可见。游戏内角色仍使用Canvas绘制。'}
function setDifficulty(event:Event){work.value={...work.value,difficulty:Number((event.target as HTMLSelectElement).value),updatedAt:new Date().toISOString()};notice.value=`已切换到第 ${work.value.difficulty} 关 · 难度 ${work.value.difficulty}，点击开始试玩。`}
function restore(item:GameWork){replay.cancel();replayMode.value=false;input.value='';selectedElement.value=undefined;editMode.value=false;stage.value=5;messages.value=[];work.value=normalizeWork(item);notice.value='已恢复作品，点击开始试玩。'}
</script>
<template>
 <div class="studio creator-workspace" :class="{'play-only':playOnly}">
  <CreatorHeader mode="网页小游戏创作"><div class="top-actions"><button v-if="playOnly" @click="playOnly=false">创作我的版本</button><template v-else><button @click="save" :disabled="running||stage<5">保存作品</button><div class="source-download"><button @click="downloadSource" :disabled="running||stage<5">下载源码</button><select v-model="sourceFormat" aria-label="源码工程格式" :disabled="running||stage<5"><option value="web-js">Web · JavaScript工程 ZIP</option><option value="vite-ts">Web · TypeScript/Vite工程 ZIP</option><option value="single-html">Web · 单文件HTML（便携）</option></select></div><button class="primary" @click="share" :disabled="running||stage<5">分享试玩 ↗</button></template></div></CreatorHeader>
  <template v-if="!playOnly"><section class="examples"><button v-for="example in examples" :key="example.kind" :class="{active:work.kind===example.kind}" @click="choose(example.kind)"><span class="example-icon">{{example.icon}}</span><span><b>{{example.name}}</b><small>{{example.description}}</small></span><span class="example-arrow">↗</span></button></section></template>
  <details v-if="!playOnly" class="engine-panel"><summary>源码工程与部署</summary><div><b>网页游戏工程与发布</b><p>JavaScript / Canvas / Three.js，素材随工程一起导出。</p></div><button @click="downloadDeployment">下载Cloudflare部署包</button><button @click="hostedPreview=!hostedPreview">{{hostedPreview?'返回制作预览':'查看已托管游戏'}}</button></details>
  <div v-if="notice" class="notice" role="status">{{notice}}</div>
  <div v-if="shareUrl" class="share-link"><label for="shareUrl">公开试玩链接</label><input id="shareUrl" :value="shareUrl" readonly @focus="($event.target as HTMLInputElement).select()"/><button @click="shareUrl=''">收起</button></div>
  <main class="workspace">
   <aside v-if="!playOnly" class="conversation inspector">
 <div class="panel-heading"><h2>调整你的游戏</h2><span>边玩边改</span></div>
 <div class="inspector-tabs"><button :class="{active:inspectorTab==='objects'}" @click="inspectorTab='objects'">对象与属性</button><button :class="{active:inspectorTab==='assets'}" @click="inspectorTab='assets'">项目素材</button></div>
 <section v-if="inspectorTab==='objects'" class="object-panel">
  <div class="object-heading"><b>游戏对象</b><button @click="toggleElements" :disabled="stage<5">{{editMode?'结束点选':'在游戏中点选'}}</button></div>
  <p class="panel-help">选择一个对象，查看属性或描述你想修改的效果。</p>
  <div class="object-list"><button v-for="element in availableElements" :key="element.id" :class="{active:selectedElement?.id===element.id}" :disabled="stage<5" @click="selectObject(element)">{{elementNames[element.id]}}</button></div>
  <div v-if="selectedElement" class="properties"><div class="object-heading"><b>{{elementNames[selectedElement.id]}}</b><button @click="selectedElement=undefined">取消选择</button></div><label v-for="property in objectProperties" :key="property.key"><span>{{property.name}}</span><input :aria-label="property.name" :type="property.key==='color'?'color':'number'" :value="property.value" :step="['scale','speed'].includes(property.key)?.1:1" @change="updateProperty(property.key,$event)"></label><small>修改后会重新开始一局；敌人属性影响同类敌人。</small></div>
  <div v-else class="empty-selection"><span>◎</span><p>从上方选择对象<br>或点选右侧游戏中的角色</p></div>
 </section>
 <section v-else class="inline-assets"><p class="panel-help">游戏引用的本地素材，随源码一起导出。</p><article v-for="asset in artAssets.filter(a=>a.kind===work.kind)" :key="asset.id"><button class="asset-thumb" :style="{backgroundImage:'url('+artUrl+')',backgroundPosition:asset.position}" @click="selectedAsset=asset"></button><b>{{asset.name}}</b><p>AI美术 · PNG · 游戏封面</p><button @click="selectedAsset=asset">查看素材</button><button @click="applyArt">应用封面</button></article><article v-if="work.kind==='tiles'"><img :src="runtimeUrl.replace('runtime.js','farm-atlas.png')" alt="农场游戏图案"><b>农场图案集</b><p>卡牌图案 · PNG · AI美术</p><a :href="runtimeUrl.replace('runtime.js','farm-atlas.png')" download>下载原图</a></article><article v-for="model in work.kind==='zombies'?modelAssets:[]" :key="model.name"><img :src="runtimeUrl.replace('runtime.js',model.preview)" :alt="model.name"><b>{{model.name}}</b><p>3D模型 · GLB · Kenney CC0</p><a :href="runtimeUrl.replace('runtime.js',model.path)" download>下载模型</a></article><p v-if="work.kind==='history'" class="panel-help">角色、飞刀和江湖场景由Canvas绘制，属性可在「对象与属性」中调整。</p></section>
